function delay(value, ms) {
  return new Promise((resolve) => setTimeout(() => resolve(value), ms));
}

async function main() {
  const results = await Promise.all([delay('A', 30), delay('B', 10), delay('C', 20)]);
  console.log(results);
}

main();

