let unsafeBalance = 100;
const withdrawals = [30, 40];

const snapshot = unsafeBalance;
withdrawals.forEach((amount) => {
  unsafeBalance = snapshot - amount;
});

const safeBalance = withdrawals.reduce((balance, amount) => balance - amount, 100);

console.log('模擬遺失更新的結果：', unsafeBalance);
console.log('安全累加的結果：', safeBalance);

